// The Dealshape logo: mark plus wordmark, from public/brand/wordmark.svg (generated by docs/brand/make_logo.py). Sizes in logo.js.
import { NAME } from "./brand.js";
import { TOP_BAR_LOGO_HEIGHT, logoSize } from "./logo.js";

export default function Logo({ height = TOP_BAR_LOGO_HEIGHT }) {
  return <img className="brand-logo" src="/brand/wordmark.svg" alt={NAME} {...logoSize(height)} />;
}
